function clean(w: string): string {
  return w.toLowerCase().replace(/[¿¡.,!?;:"""‘’()—–«»\d/]/g, '').trim();
}

export function lookupWord(raw: string): DictEntry | null {
  const w = clean(raw);
  if (!w) return null;
  if (dict[w]) return dict[w];

  // Strip trailing apostrophe contractions: 'n (yn), 'r (y/yr), 'i (ei), 'w, 'ch, 'th, 'u
  if (w.includes("'")) {
    const parts = w.split("'");
    const base = parts[0];
    if (base && dict[base]) return dict[base];
    // Try each part
    for (const p of parts) {
      if (p && dict[p]) return dict[p];
    }
    // Try base through mutation chains (e.g., byddai'n → byddai is in dict)
    if (base) {
      // Recurse into the rest of lookupWord logic for the base
      const baseResult = lookupWord(base);
      if (baseResult) return baseResult;
    }
  }

  // Soft mutation reverse: try restoring original consonant
  const softReverse: Record<string, string[]> = {
    'g': ['c'], 'b': ['p'], 'd': ['t'], 'f': ['b', 'm'], 'dd': ['d'], 'l': ['ll'], 'r': ['rh'],
  };
  for (const [mut, originals] of Object.entries(softReverse)) {
    if (w.startsWith(mut)) {
      for (const orig of originals) {
        const candidate = orig + w.slice(mut.length);
        if (dict[candidate]) return dict[candidate];
      }
    }
  }

  // G-drop in soft mutation: g disappears entirely (gradd→radd, gwaith→waith, gwyn→wyn)
  if (w.length > 1) {
    const candidate = 'g' + w;
    if (dict[candidate]) return dict[candidate];
  }

  // H-prothesis: h added before vowel (ei hanfon ← anfon, ei hiechyd ← iechyd)
  if (w.startsWith('h') && w.length > 2 && 'aeiouwyâêîôûŵŷ'.includes(w[1])) {
    const candidate = w.slice(1);
    if (dict[candidate]) return dict[candidate];
  }

  // Nasal mutation reverse
  const nasalReverse: [string, string][] = [
    ['ngh', 'c'], ['mh', 'p'], ['nh', 't'], ['ng', 'g'], ['m', 'b'], ['n', 'd'],
  ];
  for (const [mut, orig] of nasalReverse) {
    if (w.startsWith(mut)) {
      const candidate = orig + w.slice(mut.length);
      if (dict[candidate]) return dict[candidate];
    }
  }

  // Aspirate mutation reverse
  const aspReverse: [string, string][] = [
    ['ch', 'c'], ['ph', 'p'], ['th', 't'],
  ];
  for (const [mut, orig] of aspReverse) {
    if (w.startsWith(mut)) {
      const candidate = orig + w.slice(mut.length);
      if (dict[candidate]) return dict[candidate];
    }
  }

  // Verb conjugation suffix stripping
  const verbSuffixes = ['ais', 'aist', 'odd', 'oedd', 'on', 'och', 'wyd', 'wch', 'ir', 'wn', 'ith'];
  for (const suf of verbSuffixes) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dict[base]) return dict[base];
      // Try base + common infinitive endings
      for (const inf of ['u', 'i', 'o', 'io', 'ed', 'yd', 'a', 'eg']) {
        if (dict[base + inf]) return dict[base + inf];
      }
      // Try base with soft mutation reversed too
      for (const [mut, originals] of Object.entries(softReverse)) {
        if (base.startsWith(mut)) {
          for (const orig of originals) {
            const cand = orig + base.slice(mut.length);
            if (dict[cand]) return dict[cand];
            for (const inf of ['u', 'i', 'o', 'io', 'ed', 'yd', 'a']) {
              if (dict[cand + inf]) return dict[cand + inf];
            }
          }
        }
      }
    }
  }

  // Noun plural/abstract suffixes
  const nounSuffixes = ['au', 'iau', 'oedd', 'od', 'ion', 'ydd', 'wr', 'wyr', 'es',
                        'iadau', 'iant', 'iaeth', 'ad', 'edd', 'iant', 'eg', 'ach', 'af'];
  for (const suf of nounSuffixes) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dict[base]) return dict[base];
    }
  }

  // Prepositional pronouns: strip common endings
  // arna/arnat/arno/arni/arnon/arnoch/arnyn → ar
  // amdana/amdanat/amdano/amdani → am
  // wrtha/wrthat/wrtho/wrthi/wrthyn → wrth
  // ohona/ohoni/ohonyn → o
  // iddo/iddi/iddyn → i
  // gennym/gennych → gan/gen
  const prepPatterns = [
    /^(arn|amdana|amdano|amdani|amdanyn|amdanoch|amdanat)/, // ar, am
    /^(wrth[aoiy])/, // wrth
    /^(ohon[aoiy])/, // o
    /^(idd[oiy])/, // i
  ];
  // Simple: if starts with known preposition base, return that
  const prepBases: Record<string, string> = {
    'arnaf': 'ar', 'arna': 'ar', 'arnat': 'ar', 'arno': 'ar', 'arni': 'ar', 'arnon': 'ar', 'arnoch': 'ar', 'arnyn': 'ar',
    'amdana': 'am', 'amdanat': 'am', 'amdano': 'am', 'amdani': 'am', 'amdanon': 'am', 'amdanoch': 'am', 'amdanyn': 'am',
    'wrtha': 'wrth', 'wrthat': 'wrth', 'wrtho': 'wrth', 'wrthi': 'wrth', 'wrthon': 'wrth', 'wrthoch': 'wrth', 'wrthyn': 'wrth',
    'ohona': 'o', 'ohoni': 'o', 'ohonon': 'o', 'ohonoch': 'o', 'ohonyn': 'o',
    'iddo': 'i', 'iddi': 'i', 'iddyn': 'i',
    'ynoch': 'yn', 'ynof': 'yn',
    'gennym': 'gan', 'gennych': 'gan', 'ganddyn': 'gan',
    'ata': 'at', 'atat': 'at', 'ato': 'at', 'ati': 'at', 'aton': 'at', 'atoch': 'at', 'atyn': 'at',
  };
  if (prepBases[w] && dict[prepBases[w]]) return dict[prepBases[w]];

  // Comparative (-ach) and superlative (-af) adjective forms
  // e.g., cryfach → cryf, boethach → poeth (mutated), tlysaf → tlws
  for (const suf of ['ach', 'af']) {
    if (w.endsWith(suf) && w.length > suf.length + 1) {
      const stem = w.slice(0, -suf.length);
      if (dict[stem]) return dict[stem];
      // Common stem changes: vowel shifts
      // Try with common adjective endings
      for (const end of ['', 'n', 's', 'd', 'dd', 'b', 'th', 'g', 'l', 'r']) {
        if (dict[stem + end]) return dict[stem + end];
      }
      // Try mutation reversal on stem
      for (const [mut, originals] of Object.entries(softReverse)) {
        if (stem.startsWith(mut)) {
          for (const orig of originals) {
            const cand = orig + stem.slice(mut.length);
            if (dict[cand]) return dict[cand];
          }
        }
      }
    }
  }

  // Nasal/aspirate mutation + suffix stripping
  for (const [mut, orig] of nasalReverse) {
    if (w.startsWith(mut)) {
      const cand = orig + w.slice(mut.length);
      for (const suf of [...nounSuffixes, ...verbSuffixes]) {
        if (cand.endsWith(suf) && cand.length > suf.length + 2) {
          const base = cand.slice(0, -suf.length);
          if (dict[base]) return dict[base];
          for (const inf of ['u', 'i', 'o']) {
            if (dict[base + inf]) return dict[base + inf];
          }
        }
      }
    }
  }
  for (const [mut, orig] of aspReverse) {
    if (w.startsWith(mut)) {
      const cand = orig + w.slice(mut.length);
      for (const suf of [...nounSuffixes, ...verbSuffixes]) {
        if (cand.endsWith(suf) && cand.length > suf.length + 2) {
          const base = cand.slice(0, -suf.length);
          if (dict[base]) return dict[base];
          for (const inf of ['u', 'i', 'o']) {
            if (dict[base + inf]) return dict[base + inf];
          }
        }
      }
    }
  }

  // Soft mutation + lookup again for the whole chain
  for (const [mut, originals] of Object.entries(softReverse)) {
    if (w.startsWith(mut)) {
      for (const orig of originals) {
        const cand = orig + w.slice(mut.length);
        // Try suffix stripping on the unmutated form too
        for (const suf of [...nounSuffixes, ...verbSuffixes]) {
          if (cand.endsWith(suf) && cand.length > suf.length + 2) {
            const base = cand.slice(0, -suf.length);
            if (dict[base]) return dict[base];
            for (const inf of ['u', 'i', 'o']) {
              if (dict[base + inf]) return dict[base + inf];
            }
          }
        }
      }
    }
  }

  // G-drop + suffix stripping
  if (w.length > 2 && 'aeiouwyâêîôûŵŷ'.includes(w[0])) {
    const gCand = 'g' + w;
    for (const suf of [...nounSuffixes, ...verbSuffixes]) {
      if (gCand.endsWith(suf) && gCand.length > suf.length + 2) {
        const base = gCand.slice(0, -suf.length);
        if (dict[base]) return dict[base];
        for (const inf of ['u', 'i', 'o']) {
          if (dict[base + inf]) return dict[base + inf];
        }
      }
    }
  }

  return null;
}
